changeSet.sql:
with abbild as ( select jsonb_build_object( 'version', 1, 'einstellungen', jsonb_build_object( 'geschaeftsjahrEnde', coalesce(m.geschaeftsjahr_ende, '12-31'), 'kennungen', jsonb_build_object( 'uid', case when jsonb_typeof(m.kennungen -> 'uid') = 'string' and m.kennungen ->> 'uid' <> '' then m.kennungen -> 'uid' end, 'ibans', case when jsonb_typeof(m.kennungen -> 'ibans') = 'array' then m.kennungen -> 'ibans' else '[]'::jsonb end)), 'arten', coalesce(( select jsonb_agg(jsonb_build_object( 'code', a.code, 'name', a.name, 'beschreibung', a.beschreibung, 'gruppen', to_jsonb(coalesce(a.gruppen, '{}'::text[])), 'pflichtfelder', to_jsonb(coalesce(a.pflichtfelder, '{}'::text[])), 'zusatzSchema', to_jsonb(coalesce(a.zusatz_schema::text, '{"type":"object","properties":{},"additionalProperties":false}')), 'vertraulichkeit', a.vertraulichkeit, 'aufbewahrung', jsonb_build_object( 'jahre', a.aufbewahrung_jahre, 'ab', a.aufbewahrung_ab), 'gesetzlichePflicht', a.gesetzliche_pflicht, 'aktiv', a.aktiv) order by a.code collate "C") from dokumentart a), '[]'::jsonb) ) as inhalt from (select current_schema() as schema_name) s left join public.mandant m on m.schema_name = s.schema_name ) insert into konfiguration_version (version, wer, grund, quelle, inhalt, sha256) select 1, 'system:migration', null, 'MIGRATION', inhalt, encode(sha256(convert_to(inhalt::text, 'UTF8')), 'hex') from abbild;
alter table dokument alter column konfiguration_version drop default; alter table dokument_version alter column konfiguration_version drop default;
alter table dokument add constraint dokument_konfiguration_version_fk foreign key (konfiguration_version) references konfiguration_version (version); alter table dokument_version add constraint dokument_version_konfiguration_fk foreign key (konfiguration_version) references konfiguration_version (version);

create function dokument_konfiguration_version_vor_einfuegen() returns trigger language plpgsql as $$
begin
    if new.konfiguration_version is null then
        execute format('select max(version) from %I.konfiguration_version', tg_table_schema)
            into new.konfiguration_version;
    end if;
    return new;
end
$$

create function dokument_version_konfiguration_vor_einfuegen() returns trigger language plpgsql as $$
begin
    if new.konfiguration_version is null then
        execute format('select konfiguration_version from %I.dokument where id = $1', tg_table_schema)
            into new.konfiguration_version using new.dokument_id;
    end if;
    return new;
end
$$

create trigger konfiguration_version_nur_einfuegen before update or delete on konfiguration_version
    for each row execute function konfiguration_version_nur_einfuegen();
create trigger konfiguration_version_kein_truncate before truncate on konfiguration_version
    for each statement execute function konfiguration_version_nur_einfuegen();
create trigger dokument_konfiguration_version_vor_einfuegen before insert on dokument
    for each row execute function dokument_konfiguration_version_vor_einfuegen();
create trigger dokument_version_konfiguration_vor_einfuegen before insert on dokument_version
    for each row execute function dokument_version_konfiguration_vor_einfuegen();
